#include <cstddef>
#include <cstdint>

void* my_memmove(void* dst, const void* src, size_t n) {
    auto* d = static_cast<unsigned char*>(dst);
    auto* s = static_cast<const unsigned char*>(src);
    if (d == s || n == 0) return dst;
    // Compare as integers: relational < between unrelated pointers is unspecified in C++.
    if (reinterpret_cast<uintptr_t>(d) < reinterpret_cast<uintptr_t>(s)) {
        for (size_t i = 0; i < n; ++i) d[i] = s[i];      // dst before src: forward is safe
    } else {
        for (size_t i = n; i-- > 0;) d[i] = s[i];        // dst after src: copy backward
    }
    return dst;
}

